type Review = {
  id: string;
  title: string;
  severity: "low" | "medium" | "high";
};

const reviews: Review[] = [
  { id: "a11y", title: "Keyboard focus escapes modal", severity: "high" },
  { id: "cache", title: "Stale data after refresh", severity: "medium" }
];

export function summarizeReviews(items: Review[]) {
  const highPriority = items.filter((item) => item.severity === "high");

  return {
    total: items.length,
    highPriority: highPriority.length,
    titles: items.map((item) => item.title)
  };
}

export const summary = summarizeReviews(reviews);
